const listUnitGrams = `-- name: ListUnitGrams :many
SELECT id, grams FROM units WHERE id IN (/*SLICE:ids*/?)
`

type ListUnitGramsRow struct {
	ID    int64
	Grams sql.NullFloat64
}

func (q *Queries) ListUnitGrams(ctx context.Context, ids []int64) ([]ListUnitGramsRow, error) {
	query := listUnitGrams
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUnitGramsRow{}
	for rows.Next() {
		var i ListUnitGramsRow
		if err := rows.Scan(&i.ID, &i.Grams); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

